def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            ys = [y for y, x in comp]
            xs = [x for y, x in comp]
            r0, r1, c0, c1 = min(ys), max(ys), min(xs), max(xs)
            area = (r1-r0+1) * (c1-c0+1)
            # Rectangular colored objects may contain one-cell corruptions/noise;
            # fill their compact bounding boxes, while detached specks disappear.
            if area >= 4 and len(comp) / area >= 0.65:
                for y in range(r0, r1+1):
                    for x in range(c0, c1+1):
                        out[y][x] = color
            elif len(comp) == 1:
                y, x = comp[0]
                out[y][x] = bg
    return out
