 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Simultaneously repair cells that are surrounded by a same-color object,
    # otherwise clear isolated marked cells back to the dominant background.
    changes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            neighbors = [grid[y][x] for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0 <= y < h and 0 <= x < w]
            counts = Counter(neighbors)
            dominant, n = counts.most_common(1)[0]
            if color != dominant and n >= 3:
                changes.append((r,c,dominant))
            elif color != bg and sum(v == color for v in neighbors) == 0 and n >= 3:
                changes.append((r,c,bg))
    for r,c,v in changes:
        out[r][c] = v
    return out
